func TestNewWaitGroup(t *testing.T) {
	t.Run("stores a waitgroup in the returned context", func(t *testing.T) {
		ctx := contextx.NewWaitGroup(context.Background())
		wg, ok := contextx.WaitGroup(ctx)
		require.True(t, ok)
		require.NotNil(t, wg)
	})

	t.Run("parent context has no waitgroup", func(t *testing.T) {
		parent := context.Background()
		ctx := contextx.NewWaitGroup(parent)
		_, ok := contextx.WaitGroup(parent)
		require.False(t, ok)
		_, ok = contextx.WaitGroup(ctx)
		require.True(t, ok)
	})

	t.Run("preserves existing context values", func(t *testing.T) {
		type key struct{}
		parent := context.WithValue(context.Background(), key{}, 42)
		ctx := contextx.NewWaitGroup(parent)
		require.Equal(t, 42, ctx.Value(key{}))
		_, ok := contextx.WaitGroup(ctx)
		require.True(t, ok)
	})

	t.Run("waitgroup can be used for synchronization", func(t *testing.T) {
		ctx := contextx.NewWaitGroup(context.Background())
		wg, ok := contextx.WaitGroup(ctx)
		require.True(t, ok)
		wg.Add(2)
		go func() { wg.Done() }()
		go func() { wg.Done() }()
		wg.Wait()
	})

	t.Run("WaitGroupAdd and WaitGroupDone operate on the stored waitgroup", func(t *testing.T) {
		ctx := contextx.NewWaitGroup(context.Background())
		contextx.WaitGroupAdd(ctx, 3)
		contextx.WaitGroupDone(ctx)
		contextx.WaitGroupDone(ctx)
		contextx.WaitGroupDone(ctx)
		wg, ok := contextx.WaitGroup(ctx)
		require.True(t, ok)
		wg.Wait()
	})
}
